    int len;
    long long ans;
    int total_gcd;
    int pref_cnt;
    int suff_cnt;
    int pref_g[MAXG];
    int pref_c[MAXG];
    int suff_g[MAXG];
    int suff_c[MAXG];
} Node;

int gcd(int a, int b) {
    while (b) {
        int t = a % b;
        a = b;
        b = t;
    }
    return a;
}

long long cross(int *g1, int *c1, int n1, int *g2, int *c2, int n2) {
    long long res = 0;
    for (int i = 0; i < n1; i++) {
        for (int j = 0; j < n2; j++) {
            if (gcd(g1[i], g2[j]) > 1) {
                res += (long long)c1[i] * c2[j];
            }
        }
    }
    return res;
}

void combine(Node *res, Node *A, Node *B) {
    if (A->len == 0) {
        *res = *B;
        return;
    }
    if (B->len == 0) {
        *res = *A;
        return;
    }
    res->len = A->len + B->len;
    res->total_gcd = gcd(A->total_gcd, B->total_gcd);
    res->ans = A->ans + B->ans + cross(A->suff_g, A->suff_c, A->suff_cnt, B->pref_g, B->pref_c, B->pref_cnt);

