    for (int i = 0; i < A->pref_cnt; i++) {
        res->pref_g[cnt] = A->pref_g[i];
        res->pref_c[cnt] = A->pref_c[i];
        cnt++;
    }
    for (int i = 0; i < B->pref_cnt; i++) {
        int new_g = gcd(A->total_gcd, B->pref_g[i]);
        int count = B->pref_c[i];
        if (cnt > 0 && res->pref_g[cnt-1] == new_g) {
            res->pref_c[cnt-1] += count;
        } else {
            res->pref_g[cnt] = new_g;
            res->pref_c[cnt] = count;
            cnt++;
