        scanf("%d %d %d", &T, &X, &Y);
        if (T == 1) {
            int I = X;
            int V = Y;
            int pos = N + I - 1;
            set_leaf(&tree[pos], V);
            pos >>= 1;
            while (pos >= 1) {
                combine(&tree[pos], &tree[2 * pos], &tree[2 * pos + 1]);
                pos >>= 1;
            }
        } else {
            int E = X;
            int D = Y;
            int l = E - 1;
            int r = D;
            l += N;
            r += N;
            Node left_res, right_res;
            set_empty(&left_res);
            set_empty(&right_res);
            while (l < r) {
                if (l & 1) {
                    Node temp;
                    combine(&temp, &left_res, &tree[l]);
                    left_res = temp;
                    l++;
                }
                if (r & 1) {
                    r--;
                    Node temp;
                    combine(&temp, &tree[r], &right_res);
                    right_res = temp;
                }
                l >>= 1;
                r >>= 1;
            }
            Node result;
            combine(&result, &left_res, &right_res);
            printf("%lld\n", result.ans);
        }
    }

    free(S);
    free(tree);
    return 0;
}
