static inline int gcd_int(int a, int b) {
    while (b) {
        int t = a % b;
        a = b;
        b = t;
    }
    return a;
}

static inline void addClass(int *G, int *C, int *k, int g, int c) {
    if (c == 0) return;
    if (*k > 0 && G[*k - 1] == g) {
        C[*k - 1] += c;
    } else {
        G[*k] = g;
        C[*k] = c;
        ++(*k);
    }
}

static void makeLeaf(Node *p, int v) {
    p->len = 1;
    p->allg = v;
    p->kp = p->ks = 1;
    p->prefG[0] = p->suffG[0] = v;
    p->prefC[0] = p->suffC[0] = 1;
    p->ans = (v > 1) ? 1LL : 0LL;
}

static void mergeNode(Node *R, const Node *A, const Node *B) {
    if (A->len == 0) {
        *R = *B;
        return;
    }
    if (B->len == 0) {
        *R = *A;
        return;
    }

    int cum[MAXK];
    int sum = 0;

    for (int i = 0; i < A->ks; ++i) {
        sum += A->suffC[i];
        cum[i] = sum;
    }

    int t = A->ks - 1;
    long long cross = 0;

    for (int j = 0; j < B->kp; ++j) {
        int y = B->prefG[j];

        while (t >= 0 && gcd_int(A->suffG[t], y) == 1) {
            --t;
        }

        if (t >= 0) {
            cross += 1LL * B->prefC[j] * cum[t];
        }
    }

    R->len = A->len + B->len;
    R->allg = gcd_int(A->allg, B->allg);
    R->ans = A->ans + B->ans + cross;

    int k = 0;

    for (int i = 0; i < A->kp; ++i) {
        addClass(R->prefG, R->prefC, &k, A->prefG[i], A->prefC[i]);
    }

    for (int j = 0; j < B->kp; ++j) {
        int ng = gcd_int(A->allg, B->prefG[j]);
        addClass(R->prefG, R->prefC, &k, ng, B->prefC[j]);
    }

    R->kp = k;
    k = 0;

    for (int i = 0; i < B->ks; ++i) {
        addClass(R->suffG, R->suffC, &k, B->suffG[i], B->suffC[i]);
    }

    for (int i = 0; i < A->ks; ++i) {
        int ng = gcd_int(B->allg, A->suffG[i]);
        addClass(R->suffG, R->suffC, &k, ng, A->suffC[i]);
    }

    R->ks = k;
}

static int readInt(void) {
    int c;
    int x = 0;

    while ((c = getchar()) < '0' || c > '9') {
        if (c == EOF) return 0;
    }

    while (c >= '0' && c <= '9') {
        x = x * 10 + (c - '0');
        c = getchar();
    }

    return x;
}

int main(void) {
    int N = readInt();
    int M = readInt();

    int size = 1;
    while (size < N) size <<= 1;

    Node *tree = (Node *)calloc((size_t)(2 * size), sizeof(Node));

    for (int i = 0; i < N; ++i) {
        int v = readInt();
        makeLeaf(&tree[size + i], v);
    }

    for (int i = size - 1; i >= 1; --i) {
        mergeNode(&tree[i], &tree[2 * i], &tree[2 * i + 1]);
    }

    for (int q = 0; q < M; ++q) {
        int T = readInt();

        if (T == 1) {
            int I = readInt();
            int V = readInt();

            int idx = size + I - 1;
            makeLeaf(&tree[idx], V);

            idx >>= 1;

            while (idx >= 1) {
                mergeNode(&tree[idx], &tree[2 * idx], &tree[2 * idx + 1]);
                idx >>= 1;
            }
        } else {
            int E = readInt();
            int D = readInt();

            int l = size + E - 1;
            int r = size + D - 1;

            Node left, right, temp, res;
            left.len = 0;
            right.len = 0;

            while (l <= r) {
                if (l & 1) {
                    mergeNode(&temp, &left, &tree[l]);
                    left = temp;
                    ++l;
                }

                if (!(r & 1)) {
                    mergeNode(&temp, &tree[r], &right);
                    right = temp;
                    --r;
                }

                l >>= 1;
                r >>= 1;
            }

            mergeNode(&res, &left, &right);
            printf("%lld\n", res.ans);
        }
    }

    free(tree);
    return 0;
}
